      const ac=({Dense:new T.Color(.28,.52,1),Legere:new T.Color(.35,.6,1),Toxique:new T.Color(.55,.85,.2),Respirable:new T.Color(.25,.55,1),Tempetueuse:new T.Color(.6,.45,.85)})[p.atmos];
