      hG.addColorStop(0,"rgba(255,255,255,1)");hG.addColorStop(.3,"rgba(200,230,255,.9)");hG.addColorStop(1,"rgba(200,230,255,0)");
      hC.fillStyle=hG;hC.fillRect(0,0,64,64);
